import {initializeApp} from "firebase/app";
import {getFirestore,connectFirestoreEmulator,query,collection,orderBy,limit,getDocs} from "firebase/firestore";
const app=initializeApp({projectId:"demo-reading-club"});
const db=getFirestore(app);connectFirestoreEmulator(db,"127.0.0.1",8080);
const request=query(collection(db,"books"),orderBy("pages"),limit(2));
const result=await getDocs(request);
result.forEach(item=>console.log(item.data().pages));
